void read_input(int *n, int *threshold, int *people, int *current_lengths) {
    scanf("%d %d %d", n, threshold, people);
    for (int i = 0; i < *n; i++) scanf("%d", &current_lengths[i]);
}

int compute_days_needed(int n, int threshold, int people, int *current_lengths) {
    int ready = 0;
    for (int i = 0; i < n; i++) if (current_lengths[i] >= threshold) ready++;
    if (ready >= people) return 0;
    int days = 0;
    while (ready < people) {
        days++;
        ready = 0;
        for (int i = 0; i < n; i++) if (current_lengths[i] + days >= threshold) ready++;
    }
    return days;
}

int main() {
    int n, threshold, people, current_lengths[105];
    read_input(&n, &threshold, &people, current_lengths);
    printf("%d\n", compute_days_needed(n, threshold, people, current_lengths));
    return 0;
}
